def fill_public_keys(apps, schema_editor):
    Campaign = apps.get_model("campaigns", "Campaign")
    for campaign in Campaign.objects.all():
        campaign.public_key = secrets.token_hex(6)
        campaign.save(update_fields=["public_key"])


def hide_unstarted_strategic(apps, schema_editor):
    """Strategic campaigns that have not started stay with their managers."""
    Campaign = apps.get_model("campaigns", "Campaign")
    Campaign.objects.filter(
        kind="strategic", status__in=["draft", "scheduled"]
    ).update(undisclosed=True)


